SELECT API_SEQ AS api_seq, API_TYPE AS api_type, API_NM AS api_nm, CALLER_ID AS caller_id, TARGET_SERVICE AS target_service, HTTP_METHOD AS http_method, API_PATTERN AS api_pattern, AUTH_TYPE AS auth_type, API_DESC AS api_desc, USE_YN AS use_yn, TO_CHAR(UPDATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS updated_at, UPDATED_BY AS updated_by, TO_CHAR(CREATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS created_at, CREATED_BY AS created_by FROM ADM_API_MST WHERE API_TYPE = #{api_type}
AND USE_YN = #{use_yn}
AND ( API_NM LIKE '%' || #{keyword} || '%' OR CALLER_ID LIKE '%' || #{keyword} || '%' OR TARGET_SERVICE LIKE '%' || #{keyword} || '%' OR API_PATTERN LIKE '%' || #{keyword} || '%' OR AUTH_TYPE LIKE '%' || #{keyword} || '%' )
ORDER BY API_SEQ DESC

SELECT COUNT(1)
  FROM ADM_API_MST
 WHERE API_TYPE = #{api_type}
   AND CALLER_ID = #{caller_id}
   AND TARGET_SERVICE = #{target_service}
   AND HTTP_METHOD = #{http_method}
   AND API_PATTERN = #{api_pattern}

   AND API_SEQ != #{api_seq}

