UPDATE ADM_API_MST
   SET USE_YN = 'N',
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{updated_by,jdbcType=VARCHAR}
 WHERE API_SEQ = #{api_seq,jdbcType=NUMERIC}
